import sys
root=sys.argv[1]
p=root+"/README.md"
s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1,a[:60]
    s=s.replace(a,b)
rep("`core.fsmonitor=false`, `gc.auto=0`, `maintenance.auto=false`, `core.logallrefupdates=true`; remotes","`core.fsmonitor=false`, `gc.auto=0`, `gc.autoPackLimit=0`, `gc.autoDetach=false`, `gc.writeCommitGraph=false`, `fetch.writeCommitGraph=false`, `receive.autogc=false`, `maintenance.auto=false`, `core.logallrefupdates=true` (no git client repacks on its own under the replica; an explicit `git gc` of a client still can, see `consolidate`); remotes")
rep("| `bootstrap-archive` | `[--worktree --store]` | Write the bootstrap archive now (needs `machine.json`). |","| `bootstrap-archive` | `[--worktree --store] [--force]` | Write the bootstrap archive now (needs `machine.json`); skipped while little changed unless `--force`. |\n| `consolidate` | `[--worktree --store] [--apply]` | Plan (default) or run the pack consolidation of the worktree's `.git` (run it on the group server only). |")
rep("**What the archive carries, when it is rebuilt","""**Pack consolidation (`consolidate`, 2026-11-14).** Repacks by git clients (GitKraken opens, `git gc`) leave the same objects in many overlapping packs, and every pack is journaled to the store and copied to every machine (26.5 GiB of packs for 2.25 M distinct objects, 5.6 GiB). `consolidate --apply` (the relay of the group server runs it every `--consolidate-minutes`, default 1440, 0 = off, only when the plan shows at least 1 GiB of waste or a tmp file; the other machines never run it) works in this order, and a re-run converges from an interruption at any point: (1) one run per worktree (`.git/semio-consolidate.lock`, taken over from a dead pid), enough free space (largest kept pack × 1.5 and 3 % + 2 GiB reserve) else `space`; (2) every object (`cat-file --batch-all-objects`, loose and packed, reachable or not) is written by `pack-objects` as one new pack under a `tmp_consolidate_` staging name in `.git/objects/pack` (not shared; a crash leaves a file that the next start and the hourly tmp sweep remove) and checked with `git verify-pack`; (3) `.pack`, `.rev`, then `.idx` are renamed into place; (4) the run waits (30 min) until the store holds `.pack` and `.idx` of the new pack with their sizes (the replica publishes `.pack` first), else `unpublished` and nothing is retired; (5) the index files are compared again with the new pack first (`planPacksV1`): only packs whose every object is in it are retired, and orphans (a `.pack` without `.idx` or the reverse) older than an hour; `multi-pack-index` goes first, then per pack the `.idx` first (the pack disappears for readers atomically), then the rest; read-only files (git writes packs 0444) are made writable first where needed. The workers receive the deletes through the replica; they apply deletes only after all creations and only when every fleet index has its pack, so every object is present on every machine at every moment. The command prints one of `nothing`, `planned`, `consolidated`, `locked`, `space`, `unpublished`, `failed`; schema `🔁️replica/🧱️consolidate/🧬️schema/🔣️.json`.

**What the archive carries, when it is rebuilt""")
open(p,"w").write(s)
